var f = typeof(Unity_Inspector_Mod.ScriptManager).GetField("activeScripts", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Static);
var d = (System.Collections.IDictionary)f.GetValue(null);
var names = new List<string>();
foreach (object k in d.Keys) { var n = (string)k; if (n.StartsWith("lifecycle-")) names.Add(n); }
string log = "";
foreach (var n in names) log += n + ":" + Unity_Inspector_Mod.ScriptManager.UnloadScript(n) + " ";
int destroyed = 0;
foreach (var go in UnityEngine.Object.FindObjectsOfType<GameObject>()) if (go.name.StartsWith("Lifecycle")) { UnityEngine.Object.Destroy(go); destroyed++; }
foreach (var m in Harmony.GetAllPatchedMethods().ToList()) { var owners = Harmony.GetPatchInfo(m).Owners.ToList(); foreach (var o in owners) if (o.StartsWith("script.lifecycle-")) { new Harmony(o).Unpatch(m, HarmonyPatchType.All, o); log += "unpatched " + o + " "; } }
UnityEngine.Time.timeScale = 1f;
return "unloaded " + names.Count + " destroyed " + destroyed + " " + log;

