public class LifecycleBusyBehaviour : MonoBehaviour
{
    public static bool SleepNext;
    public static int HoldMs;

    void Update()
    {
        if (!SleepNext) return;
        SleepNext = false;
        var queue = (System.Collections.ICollection)typeof(Unity_Inspector_Mod.MainThreadDispatcher)
            .GetField("executionQueue", BindingFlags.NonPublic | BindingFlags.Static).GetValue(null);
        var start = System.DateTime.UtcNow;
        System.DateTime queued = System.DateTime.MinValue;
        while (true)
        {
            var now = System.DateTime.UtcNow;
            if (queued == System.DateTime.MinValue && queue.Count > 0) queued = now;
            if (queued != System.DateTime.MinValue && (now - queued).TotalMilliseconds >= HoldMs) break;
            if ((now - start).TotalMilliseconds >= HoldMs + 20000) break;
            System.Threading.Thread.Sleep(10);
        }
    }
}

